var ErrNetworkNotReady = errors.New("account network not ready")
var ErrProviderComputeUnsupported = errors.New("provider compute capability unavailable")

type Container struct {
	DB        *sql.DB
	Secrets   *secrets.Store
	Accounts  Repository
	Providers *providers.Registry
}
type AccountRuntime struct {

type accountCredentialSource struct {
	store     *secrets.Store
	accountID string
	ref       string
}

func (s accountCredentialSource) Get(ctx context.Context) ([]byte, error) {
	return s.store.Get(ctx, s.accountID, s.ref)

}

func (c Container) providerRegistry() (*providers.Registry, error) {
	if c.Providers == nil {
		return nil, errors.New("provider registry unavailable")
	}
	return c.Providers, nil
}

func (c Container) openDriver(ctx context.Context, cfg AccountConfig, client *http.Client) (providers.Driver, error) {
	r, err := c.providerRegistry()
	if err != nil {
		return nil, err
	}
	return r.Open(ctx, cfg.Provider, providers.OpenRequest{AccountID: cfg.ID, HTTPClient: client, Credentials: accountCredentialSource{store: c.Secrets, accountID: cfg.ID, ref: cfg.SecretRef}})
}

func computeDriver(rt AccountRuntime) (providers.ComputeDriver, error) {
	d, ok := rt.Driver.(providers.ComputeDriver)
	if !ok || d == nil {
		return nil, ErrProviderComputeUnsupported
	}
	return d, nil
}

func (c Container) Runtime(ctx context.Context, accountID string) (AccountRuntime, error) {
	if err := c.ensureActiveAccountProxy(ctx, accountID); err != nil {
		return AccountRuntime{}, err
	}
	cfg, err := c.Accounts.Account(ctx, accountID)
	if err != nil {
		return AccountRuntime{}, err
	}

cell := accounts.NewCellManager().Register(accountID)
if cfg.Network.Mode == network.RouteProxyRequired {
	if cfg.Proxy == nil {
		return AccountRuntime{}, ErrNetworkNotReady
	}
	password := []byte(nil)
	if cfg.ProxySecretRef != "" {
		password, err = c.Secrets.GetProxy(ctx, cfg.Proxy.ID, cfg.ProxySecretRef)

	if err != nil {
		return AccountRuntime{}, err
	}
	defer wipe(password)
}
gateway, err := network.NewProxyGateway(accountID, *cfg.Proxy, network.ProxyCredentials{Username: cfg.ProxyUsername, Password: string(password)})
if err != nil {
	return AccountRuntime{}, err

	}
	gate := network.AccountGate{Profile: cfg.Network, Proxy: cfg.Proxy, Health: network.HealthState{Status: cfg.Proxy.Status}}
	driver, err := c.openDriver(ctx, cfg, gateway.Client)
	if err != nil {
		return AccountRuntime{}, err
	}
	return AccountRuntime{Config: cfg, Cell: cell, Gateway: gateway, Driver: driver, Operations: jobs.SQLStore{DB: c.DB}, Gate: gate}, nil
}

bundle, err := network.NewIsolatedDirectClient(accountID)
if err != nil {
	return AccountRuntime{}, err
}
driver, err := c.openDriver(ctx, cfg, bundle.Client)
if err != nil {
	bundle.CloseIdleConnections()
	return AccountRuntime{}, err

	}
	gate := network.AccountGate{Profile: cfg.Network}
	return AccountRuntime{Config: cfg, Cell: cell, Driver: driver, Operations: jobs.SQLStore{DB: c.DB}, Gate: gate}, nil
}
func wipe(b []byte) {
	for i := range b {
		b[i] = 0
	}

var ErrProfileDisabled = errors.New("deployment profile disabled")
var ErrDatabaseTemplateNotConfigured = errors.New("database template not configured")
var ErrDatabaseTemplateUnavailable = errors.New("database template unavailable")

func (c Container) StartDeployment(ctx context.Context, accountID, profileID string) (workflow.Deployment, error) {
	if err := c.MaintainStickyIdentity(ctx, accountID); err != nil {
		return workflow.Deployment{}, err

}
profiles := workflow.ProfileStore{DB: c.DB}
profile, err := profiles.Get(ctx, profileID)
if err != nil {
	return workflow.Deployment{}, err
}
if profile.AccountID != accountID || !profile.Enabled {
	return workflow.Deployment{}, ErrProfileDisabled

}
if profile.Config.DatabaseTemplateID == "" {
	return workflow.Deployment{}, ErrDatabaseTemplateNotConfigured
}
var templateActive bool
var templatePath string
if err := c.DB.QueryRowContext(ctx, `SELECT active,storage_path FROM xui_database_templates WHERE id=$1`, profile.Config.DatabaseTemplateID).Scan(&templateActive, &templatePath); err != nil || !templateActive || templatePath == "" || templatePath == "pending" {
	return workflow.Deployment{}, ErrDatabaseTemplateUnavailable

}
// Serialize capacity admission per account. The capacity check and PLANNED
// deployment reservation share one transaction, so the next caller observes
// this reservation before it can consume the same provider slot.
tx, err := c.DB.BeginTx(ctx, nil)
if err != nil {
	return workflow.Deployment{}, err
}

defer tx.Rollback()
if _, err = tx.ExecContext(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1, 0))`, "deployment-admission:"+accountID); err != nil {
	return workflow.Deployment{}, err
}
var enabled bool
var runtimeStatus, providerState, providerError string
if err = tx.QueryRowContext(ctx, `SELECT enabled,runtime_status,provider_state,COALESCE(provider_error_state,'') FROM accounts WHERE id=$1`, accountID).Scan(&enabled, &runtimeStatus, &providerState, &providerError); err != nil || !enabled || runtimeStatus != "READY" || providerState != ProviderStateActive || providerError != "" {
	return workflow.Deployment{}, ErrCapacityUnavailable

}
cap, capErr := capacity.Read(ctx, tx, accountID, 2*time.Minute)
if capErr != nil {
	return workflow.Deployment{}, ErrCapacitySnapshotStale
}
if (cap.LimitKnown && cap.Limit < 1) || cap.Available() < 1 {
	return workflow.Deployment{}, ErrCapacityUnavailable
}

store := workflow.SQLStore{DB: tx}
d, _, err := store.Reserve(ctx, workflow.Request{AccountID: accountID, ProfileID: profileID, ClientCount: profile.Config.ClientCount, InboundID: profile.Config.InboundID, EmailPrefix: profile.Config.EmailPrefix})
if err != nil {
	return d, err
}
if err = tx.Commit(); err != nil {
	return d, err
}
